/// <summary>
/// PaffH 11.01.21
/// </summary>
/// <param name = "_PrivilegeIdentifier">NDXPrivilegeIdentifier</param>
/// <param name = "_securableType">NDXSecurableType</param>
/// <param name = "_securityResource">NDXSecurityResource</param>
/// <param name = "_forUpdate">boolean</param>
/// <returns>NDXSecurityRelatedObjectTable</returns>
static public NDXSecurityRelatedObjectTable find(NDXPrivilegeIdentifier _PrivilegeIdentifier
    , NDXSecurableType _securableType
    , NDXSecurityResource _securityResource
    , boolean _forUpdate = false)
{
    NDXSecurityRelatedObjectTable   nDXSecurityRelatedObjectTable;

    nDXSecurityRelatedObjectTable.selectForUpdate(_forUpdate);

    select firstonly nDXSecurityRelatedObjectTable
        where nDXSecurityRelatedObjectTable.PrivilegeIdentifier == _PrivilegeIdentifier
        && nDXSecurityRelatedObjectTable.SecurableType == _securableType
        && nDXSecurityRelatedObjectTable.SecurityResource == _securityResource;

    return nDXSecurityRelatedObjectTable;
}

/// <summary>
/// PaffH 11.01.21
/// find by NDXPrivilegeIdentifier
/// </summary>
/// <param name = "_PrivilegeIdentifier">NDXPrivilegeIdentifier</param>
/// <param name = "_securableType">NDXSecurableType</param>
/// <param name = "_securityResource">NDXSecurityResource</param>
/// <param name = "_doInsert">boolean</param>
/// <returns>NDXSecurityRelatedObjectTable</returns>
static NDXSecurityRelatedObjectTable findOrCreate(NDXPrivilegeIdentifier _PrivilegeIdentifier
    , NDXSecurableType _securableType
    , NDXSecurityResource _securityResource
    , boolean _doInsert = true)
{
    NDXSecurityRelatedObjectTable   nDXSecurityRelatedObjectTable = NDXSecurityRelatedObjectTable::find(_PrivilegeIdentifier, _securableType, _securityResource, true);
    if (!nDXSecurityRelatedObjectTable)
    {
        nDXSecurityRelatedObjectTable.PrivilegeIdentifier = _PrivilegeIdentifier;
        nDXSecurityRelatedObjectTable.SecurableType = _securableType;
        nDXSecurityRelatedObjectTable.SecurityResource = _securityResource;
        if (_doInsert)
        {
            nDXSecurityRelatedObjectTable.insert();
        }
    }
    return nDXSecurityRelatedObjectTable;
}

/// <summary>
/// PaffH 11.01.21
/// find from NDXPrivilegeTable
/// </summary>
/// <param name = "_NDXPrivilegeTable">NDXPrivilegeTable</param>
/// <param name = "_securableType">NDXSecurableType</param>
/// <param name = "_securityResource">NDXSecurityResource</param>
/// <param name = "_doInsert">boolean</param>
/// <returns>NDXSecurityRelatedObjectTable</returns>
static NDXSecurityRelatedObjectTable findOrCreateFromNDXPrivilegeTable(NDXPrivilegeTable _NDXPrivilegeTable
    , NDXSecurableType _securableType
    , NDXSecurityResource _securityResource
    , boolean _doInsert = true)
{
    NDXSecurityRelatedObjectTable   nDXSecurityRelatedObjectTable = NDXSecurityRelatedObjectTable::find(_NDXPrivilegeTable.PrivilegeIdentifier, _securableType, _securityResource, true);
    if (!nDXSecurityRelatedObjectTable)
    {
        nDXSecurityRelatedObjectTable.PrivilegeIdentifier = _NDXPrivilegeTable.PrivilegeIdentifier;
        nDXSecurityRelatedObjectTable.SecurableType = _securableType;
        nDXSecurityRelatedObjectTable.SecurityResource = _securityResource;
        nDXSecurityRelatedObjectTable.NDXPrivilegeTable = _NDXPrivilegeTable.RecId;

        if (_doInsert)
        {
            nDXSecurityRelatedObjectTable.insert();
        }
    }
    if (nDXSecurityRelatedObjectTable.NDXPrivilegeTable != _NDXPrivilegeTable.RecId)
    {
        nDXSecurityRelatedObjectTable.NDXPrivilegeTable = _NDXPrivilegeTable.RecId;
        if (_doInsert)
        {
            if (nDXSecurityRelatedObjectTable.validateWrite())
            {
                ttsbegin;
                nDXSecurityRelatedObjectTable.update();
                ttscommit;
            }
        }
    }
    return nDXSecurityRelatedObjectTable;
}

/// <summary>
/// PaffH 19.01.21
/// save NDXSecurityRelatedObjectTable from SecurityRelatedObjectRecord
/// </summary>
/// <param name = "securityRelatedObjectRecord">SecurityRelatedObjectRecord</param>
/// <param name = "nDXPrivilegeTable">NDXPrivilegeTable</param>
/// <param name = "updatedUtcDateTime">NDXUpdatedUTCDateTime</param>
/// <returns>NDXSecurityRelatedObjectTable</returns>
static NDXSecurityRelatedObjectTable saveFromSecurityRelatedObjectRecord(SecurityRelatedObjectRecord securityRelatedObjectRecord, NDXPrivilegeTable nDXPrivilegeTable, NDXUpdatedUTCDateTime updatedUtcDateTime)
{
    NDXSecurityRelatedObjectTable nDXSecurityRelatedObjectTable;
    nDXSecurityRelatedObjectTable = NDXSecurityRelatedObjectTable::findOrCreateFromNDXPrivilegeTable(
        nDXPrivilegeTable
        , securityRelatedObjectRecord.SecurableType
        , securityRelatedObjectRecord.Resource
        , false);
    nDXSecurityRelatedObjectTable.PrivilegeIdentifier = securityRelatedObjectRecord.PrivilegeIdentifier;
    nDXSecurityRelatedObjectTable.ComputedLicenseType = securityRelatedObjectRecord.ComputedLicense.LicenseType;
    nDXSecurityRelatedObjectTable.SecurableType = securityRelatedObjectRecord.SecurableType;
    nDXSecurityRelatedObjectTable.SecurityResource = securityRelatedObjectRecord.Resource;
    nDXSecurityRelatedObjectTable.UpdatedUTCDateTime = updatedUtcDateTime;

    if (nDXSecurityRelatedObjectTable.validateWrite())
    {
        ttsbegin;
        nDXSecurityRelatedObjectTable.write();
        ttscommit;
    }

    return nDXSecurityRelatedObjectTable;
}

/// <summary>
/// PaffH 20.01.21
/// delete records not updated
/// </summary>
/// <param name = "_updatedUtcDateTime">NDXUpdatedUTCDateTime</param>
/// <param name = "_logger">NDXLoggerSecurityInformationClass</param>
/// <returns>counter deleted records</returns>
static public int deleteNotUpdated(NDXUpdatedUTCDateTime _updatedUtcDateTime, NDXLoggerSecurityInformationClass _logger)
{
    NDXSecurityRelatedObjectTable nDXSecurityRelatedObjectTable;
    NDXArgsLoggerSecuritiyInformation argsLogger = new NDXArgsLoggerSecuritiyInformation();
    argsLogger.parmLogActivity(strFmt("@NDX:NDXDeleteRecordsInTable", tableId2PName(nDXSecurityRelatedObjectTable.TableId)));
    _logger.LogLineCreate(argsLogger);

    NDXHelperTable::skipForDelete(nDXSecurityRelatedObjectTable);
    delete_from nDXSecurityRelatedObjectTable
        where nDXSecurityRelatedObjectTable.UpdatedUTCDateTime != _updatedUtcDateTime;

    argsLogger.parmCounter(int642int(nDXSecurityRelatedObjectTable.RowCount()));
    _logger.LogLineChange(argsLogger);

    return int642int(nDXSecurityRelatedObjectTable.RowCount());
}

/// <summary>
/// PaffH 02.02.21
/// </summary>
public void insert()
{   
    try
    {
        super();
    }
    catch (Exception::DuplicateKeyException)
    {
        Error(strFmt("@NDX:NDXTableInsertErrorNDXSecurityRelatedObjectTable", tableId2Name(this.tableId), this.PrivilegeIdentifier, this.SecurableType, this.SecurityResource));
    }
}

/// <summary>
/// PaffH 02.02.21
/// </summary>
/// <param name = "secType">SecurableType</param>
/// <returns>MenuItemType</returns>
public MenuItemType securableTypeAsMenuItemType(SecurableType secType)
{
    MenuItemType menuItemType;
    switch (secType)
    {
        case SecurableType::MenuItemAction : 
            return MenuItemType::Action;
        case SecurableType::MenuItemDisplay : 
            return MenuItemType::Display;
        case SecurableType::MenuItemOutput : 
            return MenuItemType::Output;
    }
    return menuItemType;
}

/// <summary>
/// PaffH 01.02.21
/// try to run the menuitem
/// </summary>
public void callMenuItem()
{
    try
    {
        MenuFunction menuFunction;
        switch (this.securableTypeAsMenuItemType(this.SecurableType))
        {
            case MenuItemType::Action :
            case MenuItemType::Display :
            case MenuItemType::Output :
                menuFunction = new MenuFunction(this.SecurityResource, this.securableTypeAsMenuItemType(this.SecurableType));
                break;
            default :
                warning(strFmt("@NDX:NDXNoActionOnType", this.SecurableType));
        }
        if (menuFunction && menuFunction.checkAccessRights())
        {
            menuFunction.run();
        }
    }
    catch
    {
        Error(strFmt("@NDX:NDXMenuItemCouldNotBeOpened", this.SecurityResource));
    }
}

/// <summary>
/// PaffH 02.02.21
/// </summary>
public void MenuIterate()
{
    NDXAOTHelperMenu nDXAOTHelperMenu = NDXAOTHelperMenu::construct(this.securableTypeAsMenuItemType(this.SecurableType), this.SecurityResource);
    nDXAOTHelperMenu.iterateMenus();
    nDXAOTHelperMenu = NDXAOTHelperMenu::constructTiles(this.securableTypeAsMenuItemType(this.SecurableType), this.SecurityResource);
    nDXAOTHelperMenu.iterateMenus();
}
